.board-stats {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.stat-item {
    font-weight: 600;
    padding: 0.25rem 0.75rem;
    background: #fff;
    border-radius: 4px;
    border: 1px solid #dee2e6;
