}

.board-search {
    margin-bottom: 1rem;
}

.board-search input {
    width: 100%;
    padding: 0.5rem 1rem;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    font-size: 1rem;
}

.kanban-board {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.kanban-column {
    flex: 1;
    background: #f1f3f5;
    border-radius: 8px;
    padding: 1rem;
    min-width: 250px;
    display: flex;
    flex-direction: column;
}

.kanban-column-header h3 {
    margin: 0 0 0.75rem 0;
    font-size: 1.1rem;
}

.kanban-column-body {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    flex: 1;
}

.kanban-column-footer {
    margin-top: 0.75rem;
}

.task-card {
    background: #fff;
    border-radius: 6px;
    padding: 0.75rem;
    border: 1px solid #dee2e6;
    box-shadow: 0 1px 2px rgba(0,0,0,0.05);
}

.task-card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.5rem;
}

.task-title {
    font-weight: 600;
    font-size: 0.95rem;
}

.priority-badge {
    font-size: 0.75rem;
    padding: 0.15rem 0.5rem;
    border-radius: 10px;
    font-weight: 600;
    text-transform: uppercase;
}

.priority-high {
    background: #f8d7da;
    color: #842029;
}

.priority-medium {
    background: #fff3cd;
    color: #664d03;
}

.priority-low {
    background: #d1e7dd;
    color: #0f5132;
}

.task-card-body {
    display: flex;
    justify-content: space-between;
    font-size: 0.85rem;
    color: #6c757d;
    margin-bottom: 0.5rem;
}

.task-card-actions {
    display: flex;
    gap: 0.5rem;
}

.btn-move {
    font-size: 0.75rem;
    padding: 0.25rem 0.5rem;
    border: 1px solid #dee2e6;
    background: #fff;
    border-radius: 4px;
    cursor: pointer;
}

.btn-move:hover {
    background: #e9ecef;
}

.btn-add-task {
    width: 100%;
    padding: 0.5rem;
    border: 1px dashed #adb5bd;
    background: transparent;
    border-radius: 6px;
    cursor: pointer;
    color: #6c757d;
    font-weight: 500;
}

.btn-add-task:hover {
    background: #e9ecef;
}

.add-task-form {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.add-task-form input,
.add-task-form select {
    padding: 0.4rem 0.6rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    font-size: 0.9rem;
}

.add-task-form-actions {
    display: flex;
    gap: 0.5rem;
}

.btn-save {
    flex: 1;
    padding: 0.4rem;
    background: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.btn-cancel {
    flex: 1;
    padding: 0.4rem;
    background: #6c757d;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.board-loading {
    text-align: center;
    padding: 2rem;
    color: #6c757d;
}

.board-error {
    text-align: center;
    padding: 2rem;
    color: #dc3545;
}

.board-error button {
    margin-top: 0.5rem;
    padding: 0.5rem 1rem;
    border: 1px solid #dc3545;
    background: #fff;
    color: #dc3545;
    border-radius: 4px;
    cursor: pointer;
}

